int main(){

    string token;

    stack<int> st;

    while(cin>>token){

        if(token=="+"||token=="-"||token=="*"||token=="/"){

            int b=st.top();st.pop();

            int a=st.top();st.pop();

            if(token=="+") st.push(a+b);

            else if(token=="-") st.push(a-b);

            else if(token=="*") st.push(a*b);

            else st.push(a/b);

        } else {

            st.push(stoi(token));

        }

    }

    cout<<st.top()<<'\n';

}

